head.script:
// /* 프로그램ID */
scwin.pgmId = 'PGJ15BP01';

scwin.baseCsInfo ="";

/* 파라미터 */
scwin.schYn = "N";

/**
 *
 * onpageLoad시 법원사무소코드,사건번호로 현황조사서 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.27.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.onpageload = function() {

    //중복병합사건
    th_curstExmnDpcnMrgCs.hide();
    td_curstExmnDpcnMrgCs.hide();
    grp_rletCurstCtt.hide();
    grp_exmnDt.hide();
    const param = com.data.getParameter('paramObj');
    setTimeout(function(){
        pgjUtil.setPopUpCloseNextTabEvent($p.getFrame());
    }, 500);
    let srchCsNo = param.csNo;
    let srchCortOfcCd = param.cortOfcCd;
    if (!scutilo.isEmpty(srchCsNo) && !scutilo.isEmpty(srchCortOfcCd)) {
        dma_srchCurstExmn.set("csNo", srchCsNo)
        dma_srchCurstExmn.set("cortOfcCd", srchCortOfcCd);
        //경매 정보출처 구분코드 삽입 (현황조사서서 코드 "2")
        dma_srchCurstExmn.set("auctnInfOriginDvsCd", "2");
        com.executeSubmission(sbm_selectCurstExmn);
    }
};

scwin.onpageunload = function() {

};

//웹접근성으로 인한 title제공 수정
scwin.titleFormatter = function(){
    return "";
}

/**
 *
 * 현황조사서 조회후 화면에 맞게 데이터 셋팅
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.27.   나해준             [NELS]최초 생성
 *  2026.04.02.   강은숙             [26A-PGJ-0014] 현황조사서, 감정평가서 로봇차단솔루션 적용되게 개선
 * ============= ============ ==========================
 */
scwin.sbm_selectCurstExmn_submitdone = function(e) {

    //20260402 강은숙 [26A-PGJ-0014] 현황조사서, 감정평가서 로봇차단솔루션 적용되게 개선
    const ipcheck = e.responseJSON.data.ipcheck; //로봇탐지 결과 처리
    if(ipcheck){
        scwin.baseCsInfo = dma_curstExmnMngInf.getJSON();
        console.log("dlt_spotExmnOrdCntLst ==> ",dlt_spotExmnOrdCntLst.getAllJSON())
        // 부동산 사무소명 (타이틀)
        if (!scutilo.isEmpty(dma_curstExmnMngInf.get("cortOfcCd"))) {
            spn_curstExmnCortOfcTitle.setValue(pgjUtil.getCortOfcNm('B',dma_curstExmnMngInf.get("cortOfcCd")));
        }
        // 명령회차수 바인딩
        if (dlt_spotExmnOrdCntLst.getTotalRow()>0) {
            const spotExmnOrdCntLst = dlt_spotExmnOrdCntLst.getAllJSON();
            sbx_curstExmnOrdTs.removeAll(true)
            let ordTsCnt = scwin.baseCsInfo.ordTsCnt;
            let idx1 = 0;
            spotExmnOrdCntLst.forEach((data,i) => {
                sbx_curstExmnOrdTs.addItem(data.ordTsCnt, data.ordTsCnt, i);
                if(data.ordTsCnt == ordTsCnt){
                    idx1 = i;
                }
            });
            sbx_curstExmnOrdTs.setSelectedIndex(idx1);

            //중복,병합 사건 존재시
            if (dlt_curstExmnDpcnMrg.getTotalRow()>0) {
                th_curstExmnDpcnMrgCs.show(""); // 중복병합사건 타이틀
                td_curstExmnDpcnMrgCs.show(""); // 중복병합사건 내용
                sbx_curstExmnDpcnMrgCs.removeAll();
                let csNo = dma_curstExmnMngInf.get("csNo");
                let idx2 = 0;

                dlt_curstExmnDpcnMrg.getAllJSON().forEach( (r,i) =>{
                    sbx_curstExmnDpcnMrgCs.addItem(r.reltCsNo+'_'+r.auctnCurstExmnTrsmStatCnt, r.userRletCsNo, i);
                    if(r.reltCsNo == csNo){
                        idx2 = i;
                    }
                });
                sbx_curstExmnDpcnMrgCs.setSelectedIndex(idx2);
            }

            // 사건명
            const csNmDvsCd = !scutilo.isEmpty(dma_curstExmnMngInf.get("execIntgCsNmCd")) ? pgjUtil.getSTGcodeTaskNm('LJH','JH','AUCTN_CS_NM_CD',dma_curstExmnMngInf.get("execIntgCsNmCd")) : "";
            sbx_curstExmnBaseCsNo.setValue(`${dma_curstExmnMngInf.get("userCsNo")} ${csNmDvsCd}`);
            if (!scutilo.isEmpty(dma_curstExmnMngInf.get("exmnDtDts"))) {
                grp_exmnDt.show("");
                let tempExmnDt;
                let exmnDt = "";
                if (!scutilo.isEmpty(dma_curstExmnMngInf.get("exmnDtDts"))) {
                    tempExmnDt = dma_curstExmnMngInf.get("exmnDtDts").split("^");
                    tempExmnDt.forEach(data => {
                        exmnDt +=`${data}&nbsp;&nbsp;&nbsp`
                    })
                }
                spn_exmnDt.setValue(exmnDt);
            }
            //사진 리스트
            let picTitle = ""
            if (dlt_ordTsPicDvs.getTotalRow()>0) {
                for (let i=0; i<dlt_ordTsPicDvs.getTotalRow(); i++) {
                    if (i !== 0) {
                        picTitle +=`, `
                    }
                    let picCnt = !scutilo.isEmpty(dlt_ordTsPicDvs.getCellData(i,"cortAuctnDvsPicCnt")) ? dlt_ordTsPicDvs.getCellData(i,"cortAuctnDvsPicCnt") : 0
                    picTitle += `${pgjUtil.getSTGcodeSystemNm('PGJ','CORT_AUCTN_PIC_DVS_CD',dlt_ordTsPicDvs.getCellData(i,"cortAuctnPicDvsCd"))} ${picCnt}건`
                }
            }
            spn_picCnt.setValue(picTitle)
            // 부동산 점유관계 조사서
            if (dlt_ordTsRlet.getTotalRow()>0) {
                gen_possMng.removeAll();
                for (let i=0; i<dlt_ordTsRlet.getTotalRow(); i++) {
                    let stTitle = ""
                    let gdsCtt = dlt_ordTsRlet.getCellData(i, 'gdsPossCtt').split("\n");
                    let gdsCttTemp = "";
                    gen_possMng.insertChild(i);
                    stTitle = `${dlt_ordTsRlet.getCellData(i, 'objctSeq')}. ${dlt_ordTsRlet.getCellData(i, 'printSt')}`
                    gen_possMng.getChild(i, 'spn_possMngSt').setValue(stTitle);
                    gen_possMng.getChild(i, 'spn_possMngRltn').setValue(scwin.possRltnCdNm(dlt_ordTsRlet.getCellData(i, 'auctnPossRltnCd')));
                    if (gdsCtt.length > 0) {
                        gdsCtt.forEach(data => gdsCttTemp += `${data}<br />`)
                    }
                    gen_possMng.getChild(i, 'spn_possMngEtc').setValue(gdsCttTemp);
                }

            }

            //부동산의 현황
            if (!scutilo.isEmpty(scwin.baseCsInfo.printRltnDts)) {
                grp_rletCurstCtt.show("");
                let rletCurst = scwin.baseCsInfo.printRltnDts.split("\n")
                let tempCurst = ""
                if (rletCurst.length > 0) {
                    rletCurst.forEach(data => tempCurst += `${data}<br />`);
                }
                tbx_rletCurstCtt.setValue(tempCurst);
            }
            // TODO 웹접근성
            // tbx_rletCurstCtt.setValue("부동산 현황 테스트")

            //임차목적물의 용도 및 임대창 계약등의 내용
            if (dlt_ordTsLserLtn.getTotalRow() > 0) {
                let tempObjectSer = "";
                let cnt = 1;
                gen_tmprDbcdCtrtCtt.removeAll();
                for (let i=0; i<dlt_ordTsLserLtn.getTotalRow(); i++) {
                    let usgTemp ="";
                    gen_tmprDbcdCtrtCtt.insertChild(i);
                    //소재지별로 생성
                    if (tempObjectSer !== dlt_ordTsLserLtn.getCellData(i, 'objctSeq')) {
                        cnt = 1;
                        gen_tmprDbcdCtrtCtt.getChild(i, 'spn_tmprDbcdTitle').setValue(`[소재지] ${dlt_ordTsLserLtn.getCellData(i, 'objctSeq')}. ${dlt_ordTsLserLtn.getCellData(i, 'printSt')}`)
                    } else {
                        // gen_tmprDbcdCtrtCtt.getChild(i, 'grp_tmprDbcdTitle').setSize(null, 20);
                        gen_tmprDbcdCtrtCtt.getChild(i, 'grp_tmprDbcdTitle').hide();
                        // grp_tmprDbcdTitle.setSize(null, '20px')
                    }
                    /* 순번 */
                    gen_tmprDbcdCtrtCtt.getChild(i, 'spn_possSeq').setValue(cnt);
                    /* 점유인 */
                    gen_tmprDbcdCtrtCtt.getChild(i, 'spn_possPerson').setValue(dlt_ordTsLserLtn.getCellData(i, 'intrpsNm'));
                    /* 당사자 구분*/
                    gen_tmprDbcdCtrtCtt.getChild(i,'spn_btprtDvs').setValue(pgjUtil.getSTGcodeSystemNm('PGJ','AUCTN_INTRPS_DVS_CD',dlt_ordTsLserLtn.getCellData(i,'auctnIntrpsDvsCd')));
                    /* 점유부분 */
                    gen_tmprDbcdCtrtCtt.getChild(i,'spn_possPart').setValue(dlt_ordTsLserLtn.getCellData(i, 'lesPartCtt'))
                    /* 용도 */
                    usgTemp = pgjUtil.getSTGcodeSystemNm('PGJ','AUCTN_LES_USG_CD',dlt_ordTsLserLtn.getCellData(i,'auctnLesUsgCd'));
                    if (!scutilo.isEmpty(usgTemp) && dlt_ordTsLserLtn.getCellData(i,'auctnLesUsgCd') === '09') {
                        if (!scutilo.isEmpty(dlt_ordTsLserLtn.getCellData(i,'lesUsgDts'))) {
                            usgTemp += ` - ${dlt_ordTsLserLtn.getCellData(i,'lesUsgDts')}`
                        }
                    }
                    gen_tmprDbcdCtrtCtt.getChild(i,'spn_possUsgNm').setValue(usgTemp);
                    /* 점유기간 */
                    if ( !scutilo.isEmpty(dlt_ordTsLserLtn.getCellData(i,'gdsPossCtt')) ) {
                        gen_tmprDbcdCtrtCtt.getChild(i,'spn_possPerd').setValue(dlt_ordTsLserLtn.getCellData(i,'gdsPossCtt'));
                    }
                    /* 보증(전세)금*/
                    if ( !scutilo.isEmpty(dlt_ordTsLserLtn.getCellData(i,'lesDposDts')) ) {
                        gen_tmprDbcdCtrtCtt.getChild(i,'spn_dpos').setValue(dlt_ordTsLserLtn.getCellData(i,'lesDposDts'));
                    }
                    /* 차임 */
                    if ( !scutilo.isEmpty(dlt_ordTsLserLtn.getCellData(i,'mmrntAmtDts'))) {
                        gen_tmprDbcdCtrtCtt.getChild(i,'spn_mmrntAmt').setValue(dlt_ordTsLserLtn.getCellData(i,'mmrntAmtDts'));
                    }
                    /* 전입일자 */
                    if (!scutilo.isEmpty(dlt_ordTsLserLtn.getCellData(i,'mvinDtlCtt'))) {
                        gen_tmprDbcdCtrtCtt.getChild(i,'spn_mvinYmd').setValue(dlt_ordTsLserLtn.getCellData(i,'mvinDtlCtt'));
                    }
                    /* 확정일자 */
                    if (!scutilo.isEmpty(dlt_ordTsLserLtn.getCellData(i,'rgstryCrtcpCfmtnCtt'))) {
                        gen_tmprDbcdCtrtCtt.getChild(i,'spn_cfmtnYmd').setValue(dlt_ordTsLserLtn.getCellData(i,'rgstryCrtcpCfmtnCtt'));
                    }
                    tempObjectSer = dlt_ordTsLserLtn.getCellData(i, 'objctSeq');
                    cnt++;
                }
            } else {
                ordTsLserLtn1.hide();
                ordTsLserLtn2.hide();
            }


            /* 기타 */
            if (!scutilo.isEmpty(scwin.baseCsInfo.lesDts)) {
                let tempLes = scwin.baseCsInfo.lesDts.split("\n");
                let lesDts = ""
                if (tempLes.length > 0) {
                    tempLes.forEach(data=> lesDts += `${data}<br />`)
                }
                tbx_posEtcCtt.setValue(lesDts);
            } else {
                ordTsLserLtn3.hide();
                ordTsLserLtn4.hide();
            }

            scwin.schYn = "Y";
        } else {
            scutilo.showMsg(scglblo.MSG.WARN,"현황조사서가 존재하지 않습니다.",()=>{
                com.win.closePopup("");
            })
        }
    } else {
        scutilo.showMsg(scglblo.MSG.ERROR,e.responseJSON.message,()=>{
			com.win.closePopup("");
		});
    }
};

scwin.btn_showPicPopUp_onclick = function(e) {
    let popUpNm = "showPicOpenPopUp"
    if (!pgjUtil.popupDpcnChk(popUpNm)) {
        return;
    } else {
        scwin.showPicOpenPopUp();
    }
};

/**
 * 사진보기 팝업
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.09.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.showPicOpenPopUp = function() {
    /********* Popup Settings *********/
    var winW = window.innerWidth;
    var winH = window.innerHeight;

    /* small popup size */
    var popupW = 907;
    var popupH = 700;

    var popupX = (winW/3) - (popupW/3);
    var popupY = (winH/3) - (popupH/2.5);

    /**
     * openPopUp option설정
     */
    var options = {
        id: "showPicOpenPopUp",
        type: "wframePopup",
        popupName: "사진보기",
        top:popupY,
        left:popupX,
        width:popupW,
        height:popupH,
        modal: false
    };

    /* 팝업창이 오픈될때 같이 가져갈 paramether 변수 선언 */
    obj = {};
    paramObj = {};
    paramObj.cortOfcCd = scwin.baseCsInfo.cortOfcCd;
    paramObj.csNo = scwin.baseCsInfo.csNo;
    paramObj.ordTsCnt = scwin.baseCsInfo.ordTsCnt;
    paramObj.auctnInfOriginDvsCd = 2;
    paramObj.pgmId = scwin.pgmId;
    obj.paramObj = paramObj;
    /* 공지사항 팝업창 open  */
    com.win.openPopup("/pgj/ui/pgj100/PGJ15BP06.xml",options,obj);
};


/**
 * 이해관계인명 반환하는 메서드
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.27.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.possRltnCdNm = function(possRltnCd){
    const rltnCd = possRltnCd;
    let result = "";
    switch(rltnCd){
        case('01') : result = '채무자(소유자)점유'
            break;
        case('02') : result = '임차인(별지)점유'
            break;
        case('03') : result = '제 3 자점유'
            break;
        case('04') : result = '채무자(소유자)점유, 임차인(별지)점유, 제 3 자점유'
            break;
        case('05') : result = '채무자(소유자)점유, 임차인(별지)점유'
            break;
        case('06') : result = '임차인(별지)점유, 제 3 자점유'
            break;
        case('07') : result = '채무자(소유자)점유, 제 3 자점유'
            break;
        case('09') : result = '미상'
            break;
        case('10') : result = '기타점유'
            break;
        case('11') : result = '채무자(소유자)점유, 임차인(별지)점유, 기타점유'
            break;
        case('12') : result = '채무자(소유자)점유, 기타점유'
            break;
        case('13') : result = '임차인(별지)점유, 기타점유'
            break;
        default : result = ""
            break;
    }

    return result;
}

/**
 * 부동산표시목록 탭 클릭시 부동산표시목록을 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.27.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.tac_curstExmnRletIndct_onchange = function(tabID,idx,userTabID) {
    if (idx === 1) {
        let obj = {
        "dataObject": {"type" : "json",
                "name" : "param",
                "data" : {
                    pgmId : scwin.pgmId,
                    cortOfcCd : scwin.baseCsInfo.cortOfcCd,
                    csNo : scwin.baseCsInfo.csNo,
                    ordTsCnt : scwin.baseCsInfo.ordTsCnt,
                }
            }
        };
    wfm_rletIndctLst.setSrc('/pgj/ui/pgj100/PGJ15BP02.xml',obj)
    }
};

/**
 * 인쇄하기 버튼 클릭시 해당 화면 프린트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.27.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
  scwin.printEvent = function(e) {
    document.body.scrollTop = 0;
    let paramJSON = {};
    paramJSON.html = document.getElementById($p.getComponentById('grp_contests').id).innerHTML;

	var dataObject = {
			type : "json",
			data : paramJSON,
			name : "paramObj"
	};

    /* default popup size */
    const winW = window.innerWidth;
    const winH = window.innerHeight;
    const popupW = 1200;
    const popupH = 700;

    const popupX = (winW / 2) - (popupW / 2);
    const popupY = (winH / 2) - (popupH / 2);

	// 팝업의 옵션
	var options = {
			id: 'print',					// 팝업ID
			type: "browserPopup",			// 팝업 타입(wframePopup,browserPopup)
			width: popupW,				// 팝업 가로사이즈
			height: popupH,			// 팝업 세로사이즈
			top: popupY,					// 팝업 top위치
			left: popupX,				// 팝업 left위치
			popupName: "프린트",				// 팝업 Name
			modal: false,					// 부모창이 안움직임(true)/부모창이 움직임(false)
			useIFrame: true,
			dataObject : dataObject
	};

	$p.openPopup("/pgj/ui/pgj100/PGJPrintContainer.xml", options);
};

/**
 * 중복병합사건 select콤보박스 선택시 해당 사건번호 현황조사서 조회
 *
 *  (명령회차수가 0일경우 경고창 띄움)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.27.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbx_curstExmnDpcnMrgCs_onchange = function(info) {

    const value = info.newValue.split('_');
    /*
     * value[0] -> 사건번호
     * value[1] -> 명령회차수
     */
    console.log("value ==>",value);

    const chk = scwin.baseCsInfo.csNo;
    console.log("chk ==>",chk)

    if(chk == value[0]) return;
    const csNo = value[0];
    if (value[1]>0) {
        dma_srchCurstExmn.set("csNo", csNo);
        com.executeSubmission(sbm_selectCurstExmn);
    } else {
        scutilo.showMsg(scglblo.MSG.WARN,scutilo.getMsg(pgjmsg.PGJ.W_0059,'현황조사서'));
    }
};

/**
 * 명령최차수 콤보박스 변경시 조회
 *
 *  (명령회차수가 0일경우 경고창 띄움)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.10.15.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbx_curstExmnOrdTs_onchange = function(info) {
    if(scwin.schYn == "Y"){
        const value = info.newValue;
        if (value > 0) {
            dma_srchCurstExmn.setJSON({
                cortOfcCd : scwin.baseCsInfo.cortOfcCd,
                csNo : scwin.baseCsInfo.userCsNo,
                auctnInfOriginDvsCd :'2',
                ordTsCnt : value
            })
            com.executeSubmission(sbm_selectCurstExmn);
        } else {
            scutilo.showMsg(scglblo.MSG.WARN,scutilo.getMsg(pgjmsg.PGJ.W_0059,'현황조사서'));
        }
    }
};
